begin;
create extension if not exists pgtap with schema extensions;
select plan(37);
insert into public.b2c_students(id,source_key,full_name) values ('46100000-0000-4000-8000-000000000001','test-b2c-corrections','TEST-CORRECTIONS');
insert into public.b2c_classes(id,program_slug,name) values ('46100000-0000-4000-8000-000000000002','tieng-anh','TEST-CORRECTIONS');
insert into public.b2c_enrollments(id,source_key,class_id,student_id) values ('46100000-0000-4000-8000-000000000003','test-b2c-corrections','46100000-0000-4000-8000-000000000002','46100000-0000-4000-8000-000000000001');
select set_config('request.jwt.claims',json_build_object('sub',(select id from public.profiles where role='super_admin' and is_active limit 1),'role','authenticated')::text,true);
set local role authenticated;
select public.save_b2c_tuition_package('46100000-0000-4000-8000-000000000003',10,100000,0,'');
select public.record_b2c_tuition_receipt((select id from public.b2c_tuition_packages where enrollment_id='46100000-0000-4000-8000-000000000003'),'46100000-0000-4000-8000-000000000004','2026-10-15',600000,'cash','TEST');
select set_config('test.b2c_payload', jsonb_build_object('request_id','46100000-0000-4000-8000-000000000005','package_id',(select id from public.b2c_tuition_packages where enrollment_id='46100000-0000-4000-8000-000000000003'),'receipt_id',(select id from public.b2c_tuition_receipts where request_id='46100000-0000-4000-8000-000000000004'),'kind','refund','amount',100000,'reason','Partial refund','effective_date','2026-10-16','method','bank_transfer','reduce_fee',true,'expected_due',1000000,'expected_paid',600000)::text,true);
select ok((select relrowsecurity from pg_class where oid='public.b2c_tuition_corrections'::regclass),'Corrections have RLS');
select lives_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb)$$,'Partial refund reduces fee');
select is((public.get_b2c_tuition_page('TEST-CORRECTIONS',0)->>'total_due')::numeric,900000::numeric,'Fee reduced');
select is((public.get_b2c_tuition_page('TEST-CORRECTIONS',0)->>'paid_amount')::numeric,500000::numeric,'Net paid reduced');
select is((select amount from public.b2c_tuition_receipts where request_id='46100000-0000-4000-8000-000000000004'),600000::numeric,'Original receipt preserved');
select lives_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb)$$,'Exact retry succeeds despite changed balance');
select is((select count(*)::integer from public.b2c_tuition_corrections where package_id=(current_setting('test.b2c_payload')::jsonb->>'package_id')::uuid),1,'Retry has one ledger entry');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"reason":"different"}')$$,'22023',null,'Changed retry rejected');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"request_id":"46100000-0000-4000-8000-000000000006"}')$$,'40001',null,'Stale balance rejected');
select set_config('test.b2c_payload',(current_setting('test.b2c_payload')::jsonb||'{"request_id":"46100000-0000-4000-8000-000000000007","expected_due":900000,"expected_paid":500000,"reduce_fee":false}')::text,true);
select lives_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb)$$,'Second partial refund keeping fee');
select is((public.get_b2c_tuition_page('TEST-CORRECTIONS',0)->>'total_due')::numeric,900000::numeric,'Fee unchanged when retaining receivable');
select is((public.get_b2c_tuition_page('TEST-CORRECTIONS',0)->>'paid_amount')::numeric,400000::numeric,'Net reflects both refunds');
select set_config('test.b2c_payload',(current_setting('test.b2c_payload')::jsonb||'{"request_id":"46100000-0000-4000-8000-000000000008","expected_paid":400000}')::text,true);
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"amount":400001}')$$,'22023',null,'Over-refund rejected');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"kind":"cancel","amount":600000}')$$,'22023',null,'Cannot cancel a refunded receipt');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"reason":" "}')$$,'22023',null,'Reason required');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"effective_date":"2099-01-01"}')$$,'22023',null,'Future date rejected');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"effective_date":"2026-10-14"}')$$,'22023',null,'Refund before receipt rejected');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"amount":1.5}')$$,'22023',null,'Fractional VND rejected');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"kind":"adjust","receipt_id":null,"amount":399999}')$$,'22023',null,'Adjustment below net rejected');
select lives_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"kind":"adjust","receipt_id":null,"amount":800000}')$$,'Adjustment recorded');
select is((public.read_b2c_tuition_corrections((current_setting('test.b2c_payload')::jsonb->>'package_id')::uuid,0)->>'total')::integer,3,'History contains both refunds and adjustment');
select public.record_b2c_tuition_receipt((current_setting('test.b2c_payload')::jsonb->>'package_id')::uuid,'46100000-0000-4000-8000-000000000009','2026-10-16',400000,'cash','TEST');
select lives_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||jsonb_build_object('request_id','46100000-0000-4000-8000-000000000010','kind','cancel','receipt_id',(select id from public.b2c_tuition_receipts where request_id='46100000-0000-4000-8000-000000000009'),'amount',400000,'expected_due',800000,'expected_paid',800000))$$,'Cancel wrong receipt');
select is((public.get_b2c_tuition_page('TEST-CORRECTIONS',0)->>'paid_amount')::numeric,400000::numeric,'Cancellation excluded from totals');
select throws_ok($$delete from public.b2c_tuition_corrections$$,'42501',null,'History immutable');
select throws_ok($$update public.b2c_tuition_receipts set refunded_amount=0$$,'42501',null,'No direct settlement update');
select is((public.read_b2c_class_workspace('46100000-0000-4000-8000-000000000002','tuition',0,'',null)->'stats'->>'paid_amount')::numeric,400000::numeric,'Manager workspace uses net paid');
select is((public.read_teacher_b2c_workspace('46100000-0000-4000-8000-000000000002','tuition',0,'',null)->'stats'->>'paid_amount')::numeric,400000::numeric,'Permission workspace uses net paid');
-- Two partial refunds and one cancellation; the fee adjustment is a package event.
select is((select count(*)::integer from public.b2c_change_history where enrollment_id='46100000-0000-4000-8000-000000000003' and after_data->>'correction_reason'='Partial refund'),3,'Both refunds and cancellation audited');
select throws_ok($$select public.save_b2c_tuition_package('46100000-0000-4000-8000-000000000003',12,100000,0,'')$$,'22023',null,'Legacy edit cannot bypass required reason');
select throws_ok($$select public.save_b2c_tuition_package_with_reason('46100000-0000-4000-8000-000000000003',12,100000,0,'',' ',800000,400000)$$,'22023',null,'Package edit requires reason');
select throws_ok($$select public.save_b2c_tuition_package_with_reason('46100000-0000-4000-8000-000000000003',12,100000,0,'','New term',900000,400000)$$,'40001',null,'Package edit checks current balance');
select lives_ok($$select public.save_b2c_tuition_package_with_reason('46100000-0000-4000-8000-000000000003',12,100000,0,'','New term',800000,400000)$$,'Package quantities editable with reason');
select is((select after_data->>'adjustment_reason' from public.b2c_change_history where enrollment_id='46100000-0000-4000-8000-000000000003' and entity_type='tuition_package' order by created_at desc limit 1),'New term','Package reason in permanent audit');
select throws_ok($$insert into public.b2c_tuition_receipts(package_id,request_id,paid_date,amount,method,collector_name,refunded_amount) values ((current_setting('test.b2c_payload')::jsonb->>'package_id')::uuid,gen_random_uuid(),'2026-10-16',100000,'cash','TEST',100000)$$,'42501',null,'Direct insert cannot forge settlement');
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb||'{"request_id":"46100000-0000-4000-8000-000000000011","expected_due":1200000,"receipt_id":"46100000-0000-4000-8000-000000000099"}')$$,'22023',null,'Unrelated receipt rejected');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.correct_b2c_tuition(current_setting('test.b2c_payload')::jsonb)$$,'42501',null,'Nonmanager mutation blocked');
select throws_ok($$select public.read_b2c_tuition_corrections((current_setting('test.b2c_payload')::jsonb->>'package_id')::uuid,0)$$,'42501',null,'Nonmanager history blocked');
select * from finish();
rollback;
